import assert from 'node:assert/strict';import {readFile,writeFile} from 'node:fs/promises';import {createHash} from 'node:crypto';import {chromium} from 'playwright';import path from 'node:path';
const root=path.resolve('work/events-heldout'),record=JSON.parse(await readFile(path.join(root,'independent-event-records.json'))),browser=await chromium.launch({channel:'chrome'}),cases=[];let posts=0;
try{for(const event of record.events){assert.equal(new URL(event.url).origin,'http://127.0.0.1:9440');const response=await fetch('http://127.0.0.1:9440/wp-json/tribe/events/v1/events/'+event.id);assert.equal(response.status,200);const data=await response.json();assert.equal(data.start_date,event.definition[1]);assert.equal(data.end_date,event.definition[2]);assert.equal(data.all_day,event.definition[3]);assert.equal(data.timezone,event.definition[4]);const shots=[];
for(const width of [1440,390]){const page=await browser.newPage({viewport:{width,height:900},reducedMotion:'reduce'});await page.route('**/*',r=>{if(!['GET','HEAD'].includes(r.request().method())){posts++;return r.abort();}return new URL(r.request().url()).origin==='http://127.0.0.1:9440'?r.continue():r.abort();});assert.equal((await page.goto(event.url,{waitUntil:'networkidle'})).status(),200);await page.evaluate(()=>document.fonts.ready);assert.equal(await page.locator('.tribe-events-single-event-title').textContent(),event.definition[0]);if(!data.all_day&&data.start_date.slice(0,10)!==data.end_date.slice(0,10)){assert.equal(await page.locator('.tribe-events-start-datetime').count(),1);assert.equal(await page.locator('.tribe-events-end-datetime').count(),1);}const file=new URL(event.url).pathname.replaceAll('/','')+'-'+width+'.png';await page.screenshot({path:path.join(root,file),fullPage:true,animations:'disabled'});shots.push({width,file});await page.close();}cases.push({id:event.id,url:event.url,start:data.start_date,end:data.end_date,utcStart:data.utc_start_date,utcEnd:data.utc_end_date,allDay:data.all_day,timezone:data.timezone,definitionSHA256:createHash('sha256').update(JSON.stringify(event.definition)).digest('hex'),shots});}assert.equal(posts,0);await writeFile(path.join(root,'heldout-source-check.json'),JSON.stringify({cases,sourcePosts:posts,scope:'Independent installed source API and render verification only'},null,2));console.log(JSON.stringify({events:cases.length,screenshots:cases.flatMap(c=>c.shots).length,sourcePosts:posts}));}finally{await browser.close();}
